description:
Model a sequence lock without threads, so its logic can be tested step by step. A `SharedBlock` holds a sequence number and two values that must always be read together.

The **writer** is split into steps so tests can interleave it with readers:

- `beginWrite()` increments the sequence;
- `writeA(v)` and `writeB(v)` set the values;
- `endWrite()` increments the sequence again.

The **reader** is also split:

- `beginRead()` returns the sequence number it saw (the reader's "ticket"), or `std::nullopt` if it is odd (a write is in progress);
- `copy()` returns the two values as they are right now;
- `validate(ticket)` returns true if the sequence still equals the ticket.

Finally, `readConsistent(block)` is a complete reader using those steps: try up to 3 times; return the pair if a copy is validated, otherwise `std::nullopt`.

starter.solution.cpp:
#include <cstdint>
#include <optional>
#include <utility>

class SharedBlock
{
public:
    void beginWrite() {}
    void writeA(int v) { m_a = v; }
    void writeB(int v) { m_b = v; }
    void endWrite() {}

    std::optional<std::uint32_t> beginRead() const { return 0; }
    std::pair<int, int> copy() const { return { m_a, m_b }; }
    bool validate(std::uint32_t ticket) const { return true; }

private:
    std::uint32_t m_sequence{ 0 };
    int m_a{ 0 };
    int m_b{ 0 };
};

std::optional<std::pair<int, int>> readConsistent(const SharedBlock& block)
{
    return block.copy();
}

solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <utility>

class SharedBlock
{
public:
    void beginWrite() { ++m_sequence; }
    void writeA(int v) { m_a = v; }
    void writeB(int v) { m_b = v; }
    void endWrite() { ++m_sequence; }

    std::optional<std::uint32_t> beginRead() const
    {
        if (m_sequence & 1u) return std::nullopt;     // odd: a write is in progress
        return m_sequence;
    }
    std::pair<int, int> copy() const { return { m_a, m_b }; }
    bool validate(std::uint32_t ticket) const { return m_sequence == ticket; }

private:
    std::uint32_t m_sequence{ 0 };
    int m_a{ 0 };
    int m_b{ 0 };
};

std::optional<std::pair<int, int>> readConsistent(const SharedBlock& block)
{
    for (int attempt{ 0 }; attempt < 3; ++attempt)
    {
        const auto ticket{ block.beginRead() };
        if (!ticket) continue;
        const auto values{ block.copy() };
        if (block.validate(*ticket)) return values;
    }
    return std::nullopt;
}

unitTests:
TEST("a quiet block reads fine") { SharedBlock b; b.beginWrite(); b.writeA(1); b.writeB(2); b.endWrite(); const auto r{ readConsistent(b) }; CHECK(r.has_value()); CHECK_EQ(r->first, 1); CHECK_EQ(r->second, 2); }
TEST("no read while a write is in progress") { SharedBlock b; b.beginWrite(); CHECK(!b.beginRead().has_value()); CHECK(!readConsistent(b).has_value()); b.endWrite(); CHECK(b.beginRead().has_value()); }
TEST("a write during the copy is detected")
{
    SharedBlock b;
    const auto ticket{ b.beginRead() };
    CHECK(ticket.has_value());
    b.beginWrite(); b.writeA(10);                         // the writer starts...
    const auto torn{ b.copy() };                          // ...the reader copies half-new values...
    b.writeB(20); b.endWrite();
    CHECK_EQ(torn.first, 10); CHECK_EQ(torn.second, 0);   // a torn copy
    CHECK(!b.validate(*ticket));                          // ...and validation rejects it
}
TEST("a write that finished before the copy is fine") { SharedBlock b; b.beginWrite(); b.writeA(5); b.writeB(6); b.endWrite(); const auto t{ b.beginRead() }; const auto c{ b.copy() }; CHECK(b.validate(*t)); CHECK_EQ(c.second, 6); }
TEST("tickets are even") { SharedBlock b; for (int i{ 0 }; i < 5; ++i) { b.beginWrite(); b.endWrite(); } CHECK_EQ(*b.beginRead() % 2, 0u); }

